# 解压后的二进制数据（懒加载）
_BINARY_DATA = None


def get_binary_data() -> bytes:
    """获取解压后的二进制 IP-Country 数据（懒加载，首次调用时解压）"""
    global _BINARY_DATA
    if _BINARY_DATA is None:
        _BINARY_DATA = zlib.decompress(base64.b64decode(_COMPRESSED_B64))
    return _BINARY_DATA


def read_varint(data: bytes, offset: int) -> tuple:
    """
    从二进制数据中读取一个 varint 整数

    Returns:
        tuple: (value, new_offset)
    """
    value = 0
    shift = 0
    while True:
        byte = data[offset]
        offset += 1
        value |= (byte & 0x7F) << shift
        if not (byte & 0x80):
            break
        shift += 7
    return value, offset


